function safe(value) { return JSON.stringify(value).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/&/g, '\\u0026'); }
function exists(filename) { return Boolean(filename && fs.existsSync(filename)); }
function currentText(filename) { const document = (vscode.workspace.textDocuments || []).find((item) => path.resolve(item.fileName).toLowerCase() === path.resolve(filename).toLowerCase()); return document ? document.getText() : fs.readFileSync(filename, 'utf8'); }
function sources(defPath) { const assets = resolveAssigned(defPath); return [...new Set((assets.code || []).filter(exists).map((filename) => path.resolve(filename)))].map((filename) => ({ filename, text: currentText(filename) })); }
function cachedSff(filename) { const stat = fs.statSync(filename), key = `${stat.size}:${stat.mtimeMs}`, old = sffCache.get(filename); if (old?.key === key) return old.archive; const archive = readSff(filename); sffCache.set(filename, { key, archive }); return archive; }
function helperDraftKey(defPath) { return `helper:${sessionKey(defPath)}`; }
function safeHelperDraft(value) { try { if (!value || typeof value !== 'object') return null; return { plan: helper.normalizeHelper(value.plan), flow: helper.normalizeFlow(value.flow), editingUid: String(value.editingUid || '').slice(0, 512) }; } catch (_) { return null; } }
function helperReference(defPath, view = 'create', mode = 'basic', editingUid = '') { return { defPath: path.resolve(defPath), view: ['create','tree','flow'].includes(view) ? view : 'create', mode: mode === 'advanced' ? 'advanced' : 'basic', editingUid: String(editingUid || '') }; }
function validHelperReference(reference, defPath, model) { if (!reference || typeof reference.defPath !== 'string' || sessionKey(reference.defPath) !== sessionKey(defPath) || !['create','tree','flow'].includes(reference.view) || !['basic','advanced'].includes(reference.mode)) return false; return !reference.editingUid || Boolean(model?.graph?.nodes?.some(node => node.uid === reference.editingUid && node.type === 'helper' && !node.dynamicId)); }

function selectedProjectileDefaults(defPath, recipe) {
  const fallback = { defaults: null, label: 'Generic IKEMaker starting values' };
  try {
    const filename = metadataRegistry.find(defPath); if (!filename) return fallback;
    const loaded = metadataRegistry.read(filename), context = contextFor(defPath, loaded.root, loaded.registry);
    const selected = metadataRegistry.selection(loaded.registry.attacks, { projectId: context.project?.id, characterId: context.character?.id }) || {};
    const set = selected.projectileDefaults || loaded.registry.attacks?.projectileDefaults || {};
    const defaults = set[recipe] || set.default || null;
    return defaults ? { defaults, label: `${context.project?.name || 'Project'} profile defaults` } : fallback;
  } catch (_) { return fallback; }
}

function projectileReadiness(assets, plan) {
  const checks = [], add = (level, label, detail, file = '') => checks.push({ level, label, detail, file });
  if (!helper.PROJECTILE_RECIPES.includes(plan.recipe)) return { status: 'not-applicable', checks: [{ level: 'info', label: 'Non-projectile helper', detail: 'AIR/SFF projectile readiness checks apply only to Fireball and Super Fireball recipes.' }] };
  let action = null;
  if (!exists(assets.air)) add('error', 'AIR assignment', 'The character DEF does not point to a readable AIR file.', assets.air);
  else {
    const actions = parseAir(currentText(assets.air)); action = actions.find((item) => item.number === plan.projectile.animation);
    if (!action) add('error', `Action ${plan.projectile.animation}`, 'The projectile animation does not exist in the assigned AIR.', assets.air);
    else {
      const duration = action.frames.reduce((sum, frame) => sum + frame.time, 0), attackFrames = action.frames.filter((frame) => frame.clsn1.length), hurtFrames = action.frames.filter((frame) => frame.clsn2.length);
      add('ok', `Action ${action.number}`, `${action.frames.length} frame(s), ${duration} tick(s).`, assets.air);
      add(attackFrames.length ? 'ok' : 'error', 'Attack collision', attackFrames.length ? `${attackFrames.length} frame(s) contain Clsn1.` : 'No frame contains Clsn1, so the projectile cannot hit.', assets.air);
      add(hurtFrames.length ? 'ok' : 'warning', 'Hurt collision', hurtFrames.length ? `${hurtFrames.length} frame(s) contain Clsn2.` : 'No frame contains Clsn2. This may be intentional for an unhittable projectile.', assets.air);
    }
  }
  if (!exists(assets.sff)) add('error', 'SFF assignment', 'The character DEF does not point to a readable SFF file.', assets.sff);
  else if (action) {
    try {
      const archive = cachedSff(assets.sff), keys = new Set(archive.sprites.map((sprite) => `${sprite.group},${sprite.number}`));
      const missing = [...new Set(action.frames.map((frame) => `${frame.group},${frame.index}`).filter((key) => !keys.has(key)))];
      add(missing.length ? 'error' : 'ok', 'Sprite references', missing.length ? `Missing from SFF: ${missing.join('; ')}` : 'Every AIR frame resolves to a sprite in the assigned SFF.', assets.sff);
    } catch (error) { add('error', 'SFF parse', error.message, assets.sff); }
  }
  const status = checks.some((item) => item.level === 'error') ? 'error' : checks.some((item) => item.level === 'warning') ? 'warning' : 'ready';
  return { status, checks };
}

function previewData(assets, plan) {
  if (!helper.PROJECTILE_RECIPES.includes(plan.recipe) || !exists(assets.air) || !exists(assets.sff)) return { available: false, frames: [], path: [], playbackDefault: 'stopped' };
  try { const action = parseAir(currentText(assets.air)).find((item) => item.number === plan.projectile.animation); return projectilePreview(action, action && cachedSff(assets.sff), plan); }
  catch (error) { return { available: false, reason: error.message, frames: [], path: [], playbackDefault: 'stopped' }; }
}

function workspaceModel(defPath, plan, flow, editingUid = '') {
  const files = sources(defPath), assets = resolveAssigned(defPath), initial = plan || helper.newHelper(), profile = selectedProjectileDefaults(defPath, initial.recipe);
  const profiled = !plan && profile.defaults ? helper.applyProjectileDefaults(initial, profile.defaults) : initial;
  const graph = helper.buildHelperGraph(files), generated = helper.generateHelper(profiled), normalizedFlow = helper.normalizeFlow(flow || {}), suggestion = helper.suggestUnusedPair(files, generated.plan.id);
  const occupied = graph.nodes.filter((node) => node.type === 'helper' && Number.isInteger(node.id) && (node.id === generated.plan.id || node.stateNo === generated.plan.stateNo));
  generated.issues.push(...occupied.map((node) => ({ level: 'warning', field: 'id', message: `ID or StateDef overlaps ${node.name} at ${path.basename(node.filename)}:${node.line}. Review before inserting.` })));
  const root = gameRoot(defPath) || path.dirname(defPath), editing = graph.nodes.find((node) => node.uid === editingUid) || null;
  return { context: contextLabel(defPath), defPath, graph, dataDomains: helper.DATA_DOMAINS, plan: generated.plan, generated, flow: normalizedFlow, flowCode: helper.flowCode(normalizedFlow, generated.plan.language), suggestion, defaultsSource: profile.label, readiness: projectileReadiness(assets, generated.plan), preview: previewData(assets, generated.plan), assets: { air: assets.air || '', sff: assets.sff || '' }, roles: helper.ROLES, postypes: helper.POSTYPES, flowScopes: helper.FLOW_SCOPES, flowOperations: helper.FLOW_OPERATIONS, builtinScaffolds: helper.BUILTIN_SCAFFOLDS, recipes: recipeStore.list(fs, root).map((item) => ({ filename: item.filename, name: item.name })), editing: editing ? { uid: editing.uid, name: editing.name, filename: editing.filename, line: editing.line, dynamicId: editing.dynamicId } : null, sources: files.map((item) => ({ filename: item.filename, name: path.basename(item.filename), language: /\.zss$/i.test(item.filename) ? 'zss' : 'cns' })) };
}

