const basePage = page;
page = function enhancedHelperPage(model) {
  return basePage(model)
    .replaceAll('#111827', '#132033')
    .replaceAll('#26354b', '#34475e')
    .replaceAll('#7b8798', '#5cb6ff')
    .replace('<button data-action="refresh">Refresh</button>', '<button data-action="refresh">Refresh</button><button id="discardDraft" hidden>Discard recovered work</button><span id="draftStatus" role="status" aria-live="polite"></span>')
    .replace("view=saved.view||'create',mode=saved.mode||'basic'", "view=model.reference?.view||saved.view||'create',mode=model.reference?.mode||saved.mode||'basic'")
    .replace('render();</script>', `render();let helperStored=true;const helperBaseRender=render;render=()=>{helperBaseRender();document.querySelectorAll('#left input,#left select,#left textarea').forEach(x=>{if(!['recipeSelect','scaffoldSelect','treeFilter','flowFilter'].includes(x.id))x.addEventListener('input',()=>{helperStored=false})});document.getElementById('discardDraft').hidden=!model.recoveredDraft;document.getElementById('draftStatus').textContent=model.recoveredDraft?'Recovered unsaved Helper Lab work.':''};document.getElementById('discardDraft').onclick=()=>vscode.postMessage({type:'discardHelperDraft'});globalThis.ikemenNavigationSelection=()=>({defPath:model.defPath,view,mode,editingUid:model.editing?.uid||''});globalThis.ikemenCanRestoreNavigation=ref=>!!ref&&ref.defPath===model.defPath&&['create','tree','flow'].includes(ref.view)&&['basic','advanced'].includes(ref.mode)&&(!ref.editingUid||model.graph.nodes.some(n=>n.uid===ref.editingUid&&n.type==='helper'&&!n.dynamicId));globalThis.ikemenRestoreNavigation=ref=>{view=ref.view;mode=ref.mode;vscode.setState({view,mode});if(ref.editingUid&&ref.editingUid!==(model.editing?.uid||''))post('loadNode',{uid:ref.editingUid});else render();return true};globalThis.ikemenIsBusy=()=>!helperStored;globalThis.ikemenHasUnappliedEdits=()=>!!model.recoveredDraft||!helperStored;globalThis.ikemenCanKeepDraft=()=>helperStored;window.addEventListener('message',e=>{const m=e.data||{};if(m.type==='helperDraftStored')helperStored=true;if(m.type==='helperDraftDiscarded'){helperStored=true;model.recoveredDraft=false;document.getElementById('discardDraft').hidden=true;document.getElementById('draftStatus').textContent=''}if(m.type==='ikemenPresetCapture')vscode.postMessage({type:'ikemenPresetState',id:m.id,reference:globalThis.ikemenNavigationSelection()})});render();</script>`);
};

async function openLine(filename, line = 1) { if (!exists(filename)) return; const editor = await vscode.window.showTextDocument(await vscode.workspace.openTextDocument(vscode.Uri.file(filename)), { preview: false }); const at = new vscode.Position(Math.max(0, line - 1), 0); editor.selection = new vscode.Selection(at, at); editor.revealRange(new vscode.Range(at, at), vscode.TextEditorRevealType.InCenter); }
async function insert(filename, code) { let editor = vscode.window.visibleTextEditors.find((item) => path.resolve(item.document.fileName).toLowerCase() === path.resolve(filename || '').toLowerCase()); if (!editor && filename) editor = await vscode.window.showTextDocument(await vscode.workspace.openTextDocument(vscode.Uri.file(filename)), { preview: false }); if (!editor) return vscode.window.showWarningMessage('Choose a connected ZSS/CNS source before inserting.'); await editor.edit((edit) => edit.insert(editor.selection.active, `${editor.selection.active.character ? '\n' : ''}${code}\n`)); vscode.window.showInformationMessage('Helper code inserted. Review it or use VS Code Undo. Your Auto Save setting still applies.'); }
async function insertBoth(spawnFilename, stateFilename, spawnCode, stateCode) {
  if (!exists(spawnFilename) || !exists(stateFilename)) return vscode.window.showWarningMessage('Choose both a spawn controller file and an owned StateDef file.');
  const choice = await vscode.window.showWarningMessage(`Insert the helper spawn at the end of ${path.basename(spawnFilename)} and its owned StateDef at the end of ${path.basename(stateFilename)}? Both edits support VS Code Undo; your Auto Save setting still applies.`, { modal: true }, 'Insert Both'); if (choice !== 'Insert Both') return;
  const spawnDocument = await vscode.workspace.openTextDocument(vscode.Uri.file(spawnFilename)), stateDocument = path.resolve(stateFilename).toLowerCase() === path.resolve(spawnFilename).toLowerCase() ? spawnDocument : await vscode.workspace.openTextDocument(vscode.Uri.file(stateFilename));
  const edit = new vscode.WorkspaceEdit(), ending = (document) => document.lineAt(Math.max(0, document.lineCount - 1)).range.end;
  if (spawnDocument === stateDocument) edit.insert(spawnDocument.uri, ending(spawnDocument), `\n\n${spawnCode}\n\n${stateCode}\n`); else { edit.insert(spawnDocument.uri, ending(spawnDocument), `\n\n${spawnCode}\n`); edit.insert(stateDocument.uri, ending(stateDocument), `\n\n${stateCode}\n`); }
  await vscode.workspace.applyEdit(edit); await vscode.window.showTextDocument(stateDocument, { preview: false }); vscode.window.showInformationMessage('Spawn and StateDef inserted as one undoable workspace edit. Your Auto Save setting still applies.');
}
async function updateExisting(uid, controllerCode) {
  const fresh = workspaceModel(session.defPath, session.model.plan, session.model.flow, uid), node = fresh.graph.nodes.find((item) => item.uid === uid);
  if (!node || node.type !== 'helper') return vscode.window.showWarningMessage('That helper creation site changed or no longer exists. Refresh the tree and load it again.');
  if (node.dynamicId) return vscode.window.showWarningMessage('Computed helper IDs are inspection-only because a numeric editor could change their meaning. Open the creation site and edit the expression directly.');
  if (!controllerCode || !exists(node.filename)) return vscode.window.showWarningMessage('No safe replacement controller is available.');
  const answer = await vscode.window.showWarningMessage(`Replace only the ${node.name} creation controller in ${path.basename(node.filename)}?`, { modal: true, detail: 'The owned StateDef and all hand-authored helper behavior remain untouched. The replacement supports VS Code Undo. Your Auto Save setting still applies.' }, 'Replace Controller');
  if (answer !== 'Replace Controller') return;
  const document = await vscode.workspace.openTextDocument(vscode.Uri.file(node.filename)), current = document.getText(), expected = current.slice(node.startIndex, node.endIndex);
  if (!expected) return vscode.window.showWarningMessage('The creation controller could not be isolated safely. No code was changed.');
  const edit = new vscode.WorkspaceEdit(); edit.replace(document.uri, new vscode.Range(document.positionAt(node.startIndex), document.positionAt(node.endIndex)), controllerCode.trim());
  if (!await vscode.workspace.applyEdit(edit)) return vscode.window.showErrorMessage('VS Code did not apply the helper controller edit.');
  await vscode.window.showTextDocument(document, { preview: false }); vscode.window.showInformationMessage('Helper creation controller replaced as one undoable edit. Its StateDef was protected. Your Auto Save setting still applies.');
}
async function saveRecipe(plan) {
  const name = await vscode.window.showInputBox({ title: 'Save Helper Recipe', prompt: 'Project recipe name', placeHolder: 'Heavy Fireball' }); if (!name) return;
  const root = gameRoot(session.defPath) || path.dirname(session.defPath), filename = recipeStore.recipeFilename(root, name);
  if (exists(filename)) { const answer = await vscode.window.showWarningMessage(`Replace project recipe ${path.basename(filename)}?`, { modal: true }, 'Replace Recipe'); if (answer !== 'Replace Recipe') return; }
  transactionalWrite(fs, filename, `${JSON.stringify(recipeStore.recipeDocument(name, helper.normalizeHelper(plan)), null, 2)}\n`, optionsFromConfig(vscode, filename, 'save-helper-recipe', { journalRoot: root, allowExisting: true }));
  vscode.window.showInformationMessage(`Saved project helper recipe: ${recipeStore.cleanName(name)}`); refresh(plan);
}
function loadRecipe(filename) {
  const root = gameRoot(session.defPath) || path.dirname(session.defPath), found = recipeStore.list(fs, root).find((item) => path.resolve(item.filename).toLowerCase() === path.resolve(filename || '').toLowerCase());
  if (!found) return vscode.window.showWarningMessage('Choose an available project helper recipe.');
  session.editingUid = ''; refresh(helper.normalizeHelper(found.plan), session.model.flow);
}
async function openAsset(filename) { if (!exists(filename)) return; const uri = vscode.Uri.file(filename); if (/\.sff$/i.test(filename)) return vscode.commands.executeCommand('vscode.openWith', uri, 'ikemen.sffWorkspace', { preview: false }); if (/\.air$/i.test(filename)) return vscode.commands.executeCommand('air.openAnimationPreview', uri); return vscode.window.showTextDocument(uri, { preview: false }); }
function refresh(plan = session?.model?.plan, flow = session?.model?.flow) { if (!session) return; session.model = workspaceModel(session.defPath, plan, flow, session.editingUid); session.files = session.model.sources.map((item) => item.filename.toLowerCase()); session.panel.webview.postMessage({ type: 'model', model: session.model }); }
