async function stageOwner(owner, plan, flow) {
  const draft = safeHelperDraft({ plan, flow, editingUid: owner.editingUid });
  if (!draft) throw new Error('The Helper Lab draft is invalid.');
  owner.plan = draft.plan; owner.flow = draft.flow; owner.recoveredDraft = true;
  await formDrafts.stage(helperDraftKey(owner.defPath), draft);
  return draft;
}
